(819123, 92560, 7252, '<td valign="top">The photographic quality is quite good. Lighting is even without harsh highlights or shadows. Sharp, well exposed, clean. However, overall it just isn''t compelling. Needs something to pull it away from being just a straight forward shot.</td>', 'The photographic quality is quite good. Lighting is even without harsh highlights or shadows. Sharp, well exposed, clean. However, overall it just isn''t compelling. Needs something to pull it away from being just a straight forward shot.', '2004-07-21 01:42:27.000000', NULL, 1),
(819126, 92239, 327, '<td valign="top">Very pretty but I''d eat them just the same. YUM</td>', 'Very pretty but I''d eat them just the same. YUM', '2004-07-21 01:42:46.000000', NULL, 1),
(819127, 92578, 23100, '<td valign="top">Nicely lit. Good concept. Composition seems a little off-balance with the large black area at bottom right.  Maybe crop it at the collar bone?</td>', 'Nicely lit. Good concept. Composition seems a little off-balance with the large black area at bottom right.  Maybe crop it at the collar bone?', '2004-07-21 01:43:11.000000', NULL, 1),
