(819738, 92663, 17233, '<td valign="top">I''m finding it really hard to make this out - it doesn''t look like it contains chocolate though. I think you may have a chronic monitor calibration problem as the image lacks any contrast or clarity.</td>', 'I''m finding it really hard to make this out - it doesn''t look like it contains chocolate though. I think you may have a chronic monitor calibration problem as the image lacks any contrast or clarity.', '2004-07-21 07:38:37.000000', NULL, 1),
(819751, 91679, 17233, '<td valign="top">I like the high-key treatment of this image. The lighting is good for this effect and the shadows on the right are not too harsh and give form to the mug. Well done (8)</td>', 'I like the high-key treatment of this image. The lighting is good for this effect and the shadows on the right are not too harsh and give form to the mug. Well done (8)', '2004-07-21 07:56:07.000000', NULL, 1),
