(819788, 91912, 19446, '<td valign="top">There''s too much (digital) noise in this picture.  It''s also grainy (iso 400?), but that''s OK.  Grain &amp; noise are two different beasts.  You should download Neat Image, the basic version is free &amp; will help with this.</td>', 'There''s too much (digital) noise in this picture.  It''s also grainy (iso 400?), but that''s OK.  Grain & noise are two different beasts.  You should download Neat Image, the basic version is free & will help with this.', '2004-07-21 08:41:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(819792, 92562, 19446, '<td valign="top">Good color contrasts here.  The only thing that is bugging me are the fingerprints though.</td>', 'Good color contrasts here.  The only thing that is bugging me are the fingerprints though.', '2004-07-21 08:42:11.000000', NULL, 1),
(819795, 92656, 19446, '<td valign="top">hahaha!  Creative.</td>', 'hahaha!  Creative.', '2004-07-21 08:43:51.000000', NULL, 1),
(819799, 92684, 19446, '<td valign="top">Excellent idea &amp; composition.  I like how the diaginal lines between the chips lead the eye back to the boat from the top of the frame.</td>', 'Excellent idea & composition.  I like how the diaginal lines between the chips lead the eye back to the boat from the top of the frame.', '2004-07-21 08:46:01.000000', NULL, 1),
(819801, 92390, 19446, '<td valign="top">Good balance here.  I''m sure there''ll be a bunch of "too overexposed" comments, but the effect works well in this picture.  The only problem is that my eye is drawn to inside her nose.</td>', 'Good balance here.  I''m sure there''ll be a bunch of "too overexposed" comments, but the effect works well in this picture.  The only problem is that my eye is drawn to inside her nose.', '2004-07-21 08:48:31.000000', NULL, 1),
(819806, 92497, 19446, '<td valign="top">I really like this one.  The expression was captured perfectly.  My only constructive critisim is that I would have cropped in more from the right so the boy fills the whole frame; I might even go as far as making the right edge even with the back of his neck - It put''s his eyes at that magical 3rds point and really focuse the attention to his face.</td>', 'I really like this one.  The expression was captured perfectly.  My only constructive critisim is that I would have cropped in more from the right so the boy fills the whole frame; I might even go as far as making the right edge even with the back of his neck - It put''s his eyes at that magical 3rds point and really focuse the attention to his face.', '2004-07-21 08:52:58.000000', NULL, 1),
(819809, 92561, 19446, '<td valign="top">Please pardon my ignorance on this, but when the challenge ends, I''d love to know the "story behind the chocolate"</td>', 'Please pardon my ignorance on this, but when the challenge ends, I''d love to know the "story behind the chocolate"', '2004-07-21 08:54:29.000000', NULL, 1),
(819811, 92015, 10799, '<td valign="top">To really make this great include the whole reflection of the candy.  It seems undone without it.  I love his expression and his eyes.</td>', 'To really make this great include the whole reflection of the candy.  It seems undone without it.  I love his expression and his eyes.', '2004-07-21 08:55:38.000000', NULL, 1),
(819818, 92517, 10799, '<td valign="top">...about the title.... only if he is an idiot and in that case don''t accept the kiss! Of course, if you are male pawn the ring and eat the chocolate you are not ready for marriage with that way of thinking!  :)   I think you did a good job on this one. The ring has no reflections that distract.  The only thing I wonder is if you could have had a light shine just on the diamond to make it sparkle a bit.</td>', '...about the title.... only if he is an idiot and in that case don''t accept the kiss! Of course, if you are male pawn the ring and eat the chocolate you are not ready for marriage with that way of thinking!  :)   I think you did a good job on this one. The ring has no reflections that distract.  The only thing I wonder is if you could have had a light shine just on the diamond to make it sparkle a bit.', '2004-07-21 08:59:28.000000', NULL, 1),
(819822, 91961, 164, '<td valign="top">glare distracts - good idea</td>', 'glare distracts - good idea', '2004-07-21 09:00:37.000000', NULL, 1),
(819823, 92313, 19446, '<td valign="top">I like the bakdrop and how the creases (diagonal &amp; horizontal) lead the eye back to the subject.  The flash is a bit too harsh and casts too defined of a shadow behind the boy.  You might want to try bouncing or defusing the flash next time (can be done w/ a peice of paper if you only have the built-in flash).  My only other thought is that the blue on blue is a bit detracting.</td>', 'I like the bakdrop and how the creases (diagonal & horizontal) lead the eye back to the subject.  The flash is a bit too harsh and casts too defined of a shadow behind the boy.  You might want to try bouncing or defusing the flash next time (can be done w/ a peice of paper if you only have the built-in flash).  My only other thought is that the blue on blue is a bit detracting.', '2004-07-21 09:01:05.000000', NULL, 1),
(819827, 92647, 10799, '<td valign="top">To me the Kit Kat Wrapper is too big an area to have that much out of focus.  I think it would be ok a little soft but as far as the composition goes.... the wrapper seems to be what draws my eye.</td>', 'To me the Kit Kat Wrapper is too big an area to have that much out of focus.  I think it would be ok a little soft but as far as the composition goes.... the wrapper seems to be what draws my eye.', '2004-07-21 09:06:19.000000', NULL, 1),
(819835, 92609, 16241, '<td valign="top">nice</td>', 'nice', '2004-07-21 09:14:36.000000', NULL, 1),
(819836, 91961, 7560, '<td valign="top">This is a very American centric shot. but still a very fun idea. :) Extra points for creativity. 6</td>', 'This is a very American centric shot. but still a very fun idea. :) Extra points for creativity. 6', '2004-07-21 09:15:45.000000', NULL, 1),
(819838, 92679, 20379, '<td valign="top">There'' such a thing as chocolate soup!?<br/>I must have been living in a cave...<br/>good idea (9)</td>', 'There'' such a thing as chocolate soup!?I must have been living in a cave...good idea (9)', '2004-07-21 09:16:33.000000', NULL, 1),
(819843, 92656, 20379, '<td valign="top">i love the expression on his face!<br/>the air bubble is distracting. <br/>very funny (9)</td>', 'i love the expression on his face!the air bubble is distracting. very funny (9)', '2004-07-21 09:18:59.000000', NULL, 1),
(819845, 92276, 16241, '<td valign="top">this should be in top 3</td>', 'this should be in top 3', '2004-07-21 09:20:05.000000', NULL, 1),
(819846, 92243, 24125, '<td valign="top">Nice use of focus and lighting to draw attention to the subject. The dark shadows are a little distracting. Very clever placement of the isolated "kiss".. I actually feel sorry for it :) 8/10</td>', 'Nice use of focus and lighting to draw attention to the subject. The dark shadows are a little distracting. Very clever placement of the isolated "kiss".. I actually feel sorry for it :) 8/10', '2004-07-21 09:22:40.000000', NULL, 1),
(819847, 92421, 14614, '<td valign="top">I would [refer a plainer background and a bit sharper focus on the right fork.  Off center composition works well</td>', 'I would [refer a plainer background and a bit sharper focus on the right fork.  Off center composition works well', '2004-07-21 09:23:14.000000', NULL, 1),
(819848, 92656, 16241, '<td valign="top">hilarious</td>', 'hilarious', '2004-07-21 09:23:26.000000', NULL, 1),
(819849, 92134, 14614, '<td valign="top">a bit too much going on here.  simplify your composition by adding some blank (negative) space.  The red stands out well -- couldn''t resist a bite? ;)</td>', 'a bit too much going on here.  simplify your composition by adding some blank (negative) space.  The red stands out well -- couldn''t resist a bite? ;)', '2004-07-21 09:24:53.000000', NULL, 1),
(819850, 92644, 10785, '<td valign="top">Who goes to work wearing a Boa and carrying a briefcase?</td>', 'Who goes to work wearing a Boa and carrying a briefcase?', '2004-07-21 09:25:31.000000', NULL, 1),
(819851, 92282, 16493, '<td valign="top">The strawberries look good but the chocolate not.</td>', 'The strawberries look good but the chocolate not.', '2004-07-21 09:25:52.000000', NULL, 1),
(819852, 92684, 15891, '<td valign="top">Very creative concept! The chocolate looks a little grainy but I''m certainly not going to deduct points for that as I''m sure the choco-chip makers didn''t produces these little gems of goodness with photographers in mind, right?</td>', 'Very creative concept! The chocolate looks a little grainy but I''m certainly not going to deduct points for that as I''m sure the choco-chip makers didn''t produces these little gems of goodness with photographers in mind, right?', '2004-07-21 09:26:28.000000', NULL, 1),
(819853, 91994, 14614, '<td valign="top">putting the hand in focus was a good use of dof, I''d like a bit more of it showing.  Straightening the tilted horizon and the wrinkled cloth would help.</td>', 'putting the hand in focus was a good use of dof, I''d like a bit more of it showing.  Straightening the tilted horizon and the wrinkled cloth would help.', '2004-07-21 09:26:36.000000', NULL, 1),
(819854, 92517, 15891, '<td valign="top">Hmmm... are you one of those folks who think "happily married" is an oxymoron?<br/>Nice shot, nicely lit. Seems a little out of focus, however.</td>', 'Hmmm... are you one of those folks who think "happily married" is an oxymoron?Nice shot, nicely lit. Seems a little out of focus, however.', '2004-07-21 09:28:07.000000', NULL, 1),
(819856, 92541, 15891, '<td valign="top">Cute concept and creative composition. The lighting leaves a little to be desired IMO. The chocolate just seems to have an odd color cast. A nice photo regardless.</td>', 'Cute concept and creative composition. The lighting leaves a little to be desired IMO. The chocolate just seems to have an odd color cast. A nice photo regardless.', '2004-07-21 09:31:03.000000', NULL, 1),
(819858, 92580, 15891, '<td valign="top">The lighting in this photo is lovely!</td>', 'The lighting in this photo is lovely!', '2004-07-21 09:33:07.000000', NULL, 1),
(819859, 92642, 15891, '<td valign="top">This is a very clever concept. I would have liked to have seen more of the rippling chocolate. Or put another way, I would like to see this image not cropped quite so tight.</td>', 'This is a very clever concept. I would have liked to have seen more of the rippling chocolate. Or put another way, I would like to see this image not cropped quite so tight.', '2004-07-21 09:34:39.000000', NULL, 1),
(819860, 92561, 14614, '<td valign="top">Quite powerful -- I like your approach.  Thoughts below as I study your shot...<br/> <br/>There are some compositional  aspects that take away from your full impact for me.  A plainer section of wrapper would work instead of the bar code, the brighter chocolate bar (?) upper right distracts (making it more like the lower left one may work better) -- I like the placement of the face and that it''s the brightest part of the shot.  The patch to the right of the face is a bit odd in that you have drawn my eye there but I''m not sure what I''m to see.</td>', 'Quite powerful -- I like your approach.  Thoughts below as I study your shot... There are some compositional  aspects that take away from your full impact for me.  A plainer section of wrapper would work instead of the bar code, the brighter chocolate bar (?) upper right distracts (making it more like the lower left one may work better) -- I like the placement of the face and that it''s the brightest part of the shot.  The patch to the right of the face is a bit odd in that you have drawn my eye there but I''m not sure what I''m to see.', '2004-07-21 09:34:59.000000', NULL, 1),
(819861, 91993, 15891, '<td valign="top">Ha ha ha! Very cute!</td>', 'Ha ha ha! Very cute!', '2004-07-21 09:35:33.000000', NULL, 1),
(819862, 92242, 14614, '<td valign="top">a bit deeper dof would keep the spoon in focus (I like the blurred backdrop) the lighting is flat -- playing with it may help add some punch.</td>', 'a bit deeper dof would keep the spoon in focus (I like the blurred backdrop) the lighting is flat -- playing with it may help add some punch.', '2004-07-21 09:36:43.000000', NULL, 1),
(819864, 92410, 15891, '<td valign="top">This is nice... perpahps a little more frontal lighting would give this image more pop.</td>', 'This is nice... perpahps a little more frontal lighting would give this image more pop.', '2004-07-21 09:37:34.000000', NULL, 1),
(819865, 92280, 14614, '<td valign="top">Funny idea.  Crisper focus on the berries and less-flat lighting would make this a bit more interesting</td>', 'Funny idea.  Crisper focus on the berries and less-flat lighting would make this a bit more interesting', '2004-07-21 09:37:52.000000', NULL, 1),
(819866, 92399, 10799, '<td valign="top">I would like to see this larger using all your alloted 640 size limits.  The flash is a bit distracting.  I don''t know if you could get the flash to reflect in the whip cream to hide the effects but it is a thought.</td>', 'I would like to see this larger using all your alloted 640 size limits.  The flash is a bit distracting.  I don''t know if you could get the flash to reflect in the whip cream to hide the effects but it is a thought.', '2004-07-21 09:38:02.000000', NULL, 1),
(819867, 92380, 14614, '<td valign="top">doesn''t captivate my interest - I need more in a main subject.  Sorry</td>', 'doesn''t captivate my interest - I need more in a main subject.  Sorry', '2004-07-21 09:38:46.000000', NULL, 1),
(819868, 91563, 14614, '<td valign="top">Funny title and idea.  I''d like to see all 4 smiles in the frame.  A more even light would take away the hot spot from the wrapper and even out the colors on the background.</td>', 'Funny title and idea.  I''d like to see all 4 smiles in the frame.  A more even light would take away the hot spot from the wrapper and even out the colors on the background.', '2004-07-21 09:40:20.000000', NULL, 1),
(819869, 92499, 14614, '<td valign="top">excellent composition -- lighting is tough as I''d like the main subject a bit crisper.  your simple apporach works well.</td>', 'excellent composition -- lighting is tough as I''d like the main subject a bit crisper.  your simple apporach works well.', '2004-07-21 09:42:00.000000', NULL, 1),
(819870, 92626, 14614, '<td valign="top">a bit small to see what you have created here.  looks a bit fuzzy but hard to tell -- Sorry I cannot offer any other comments.  I''d suggest using the full 640 on one side to enlarge your entries</td>', 'a bit small to see what you have created here.  looks a bit fuzzy but hard to tell -- Sorry I cannot offer any other comments.  I''d suggest using the full 640 on one side to enlarge your entries', '2004-07-21 09:43:43.000000', NULL, 1),
(819873, 92608, 14614, '<td valign="top">one of the best lit entries,  a plainer plate would keep my attention on your main subject.  the orange peal on the side of the plate isn''t appetizing and I think removing it would help simplify the composition.</td>', 'one of the best lit entries,  a plainer plate would keep my attention on your main subject.  the orange peal on the side of the plate isn''t appetizing and I think removing it would help simplify the composition.', '2004-07-21 09:45:36.000000', NULL, 1),
(819874, 92399, 14614, '<td valign="top">Too small to really see what you''ve created.</td>', 'Too small to really see what you''ve created.', '2004-07-21 09:45:56.000000', NULL, 1),
(819875, 92243, 15891, '<td valign="top">Ahhh... somebody give the little guy a hug!<br/>Very creative and I like the lighting. The paper the chocolates are sitting on is a little distracting though - I would have liked to see something smoother. I''m giving you a 9 anyway. You have managed to make chocolate emotive which is no small task at all!</td>', 'Ahhh... somebody give the little guy a hug!Very creative and I like the lighting. The paper the chocolates are sitting on is a little distracting though - I would have liked to see something smoother. I''m giving you a 9 anyway. You have managed to make chocolate emotive which is no small task at all!', '2004-07-21 09:47:10.000000', NULL, 1),
(819881, 92663, 16004, '<td valign="top">i''m having a great deal of difficulty deciphering this.  the image is too pale / bright to work as a conceptual piece of astract; it''s just lacking in depth really.  also, i''m not sure what "gadive" is (unless it''s a typo of "Godiva"), and it being green and all blurry just makes it a little strange for my tastes.  have to be a meany re the score here.  sorry.</td>', 'i''m having a great deal of difficulty deciphering this.  the image is too pale / bright to work as a conceptual piece of astract; it''s just lacking in depth really.  also, i''m not sure what "gadive" is (unless it''s a typo of "Godiva"), and it being green and all blurry just makes it a little strange for my tastes.  have to be a meany re the score here.  sorry.', '2004-07-21 09:56:23.000000', NULL, 1),
(819883, 92613, 15891, '<td valign="top">Eewww... I''m afraid I don''t like this concept at all. The baby looks unhappily confused.</td>', 'Eewww... I''m afraid I don''t like this concept at all. The baby looks unhappily confused.', '2004-07-21 09:58:27.000000', NULL, 1),
(819884, 92450, 21495, '<td valign="top">Well done!!!!</td>', 'Well done!!!!', '2004-07-21 09:58:46.000000', NULL, 1),
(819888, 92578, 7291, '<td valign="top">uummm.........yum!</td>', 'uummm.........yum!', '2004-07-21 10:07:28.000000', NULL, 1),
