(820093, 92675, 19425, '<td valign="top">Damn, that chocolate looks good. I like how your photo really makes the chocolate look delicious.</td>', 'Damn, that chocolate looks good. I like how your photo really makes the chocolate look delicious.', '2004-07-21 11:59:40.000000', NULL, 1),
(820094, 92560, 14614, '<td valign="top">like the way you filled the frame...lighting is a bit flat and could be used more as an element to make the shot more enteresting.</td>', 'like the way you filled the frame...lighting is a bit flat and could be used more as an element to make the shot more enteresting.', '2004-07-21 12:00:10.000000', NULL, 1),
