(820616, 92396, 24169, '<td valign="top">A nice close up but I''m not sure what to think.</td>', 'A nice close up but I''m not sure what to think.', '2004-07-21 16:47:24.000000', NULL, 1),
(820618, 92671, 19333, '<td valign="top">I''ve thought doing a Toblerone too, but may have NEVER thought involving a viper with it. Chocolate is not a so big sin!!</td>', 'I''ve thought doing a Toblerone too, but may have NEVER thought involving a viper with it. Chocolate is not a so big sin!!', '2004-07-21 16:47:42.000000', NULL, 1),
