(820928, 92524, 8816, '<td valign="top">I would say that this is a very well composed abstract.  My favourite abstracts are the ones where the subject appears to be something completely different then what it actually is due to the angle and composition of the image.  This looks like a keyboard or something!  Well taken.  DOF is good, as is exposure - you could have very easily over-exposed the image!  8</td>', 'I would say that this is a very well composed abstract.  My favourite abstracts are the ones where the subject appears to be something completely different then what it actually is due to the angle and composition of the image.  This looks like a keyboard or something!  Well taken.  DOF is good, as is exposure - you could have very easily over-exposed the image!  8', '2004-07-21 19:59:52.000000', NULL, 1),
(820930, 92390, 4871, '<td valign="top">I would have rated higher if the exposure was better. Great shot,  just a bit blown out.</td>', 'I would have rated higher if the exposure was better. Great shot,  just a bit blown out.', '2004-07-21 20:00:32.000000', NULL, 1),
(820934, 92684, 4871, '<td valign="top">O</td>', 'O', '2004-07-21 20:01:48.000000', NULL, 1),
(820944, 92243, 20021, '<td valign="top">interesting POV....</td>', 'interesting POV....', '2004-07-21 20:11:48.000000', NULL, 1),
(820970, 92244, 22010, '<td valign="top">Wow. This is a really nice shot! The color and focus is perfect. So is the background. My favorite of the this challenge.</td>', 'Wow. This is a really nice shot! The color and focus is perfect. So is the background. My favorite of the this challenge.', '2004-07-21 20:40:16.000000', NULL, 1),
(820971, 91771, 22010, '<td valign="top">There were many strawberry dipped in chocolate shots. This is my favorite of the lot and one of my favorites of the whole challenge. The background is very nice!!</td>', 'There were many strawberry dipped in chocolate shots. This is my favorite of the lot and one of my favorites of the whole challenge. The background is very nice!!', '2004-07-21 20:42:22.000000', NULL, 1),
(820974, 92282, 22010, '<td valign="top">I really like the colors. Just about everything is in focus. My eyes go straight for the contents of the bowl. Very nice!</td>', 'I really like the colors. Just about everything is in focus. My eyes go straight for the contents of the bowl. Very nice!', '2004-07-21 20:44:02.000000', NULL, 1),
(820976, 92218, 22010, '<td valign="top">Me too! I like the lighting, idea, and execution very much. Good luck.</td>', 'Me too! I like the lighting, idea, and execution very much. Good luck.', '2004-07-21 20:45:25.000000', NULL, 1),
(820978, 91679, 22010, '<td valign="top">I like how the left edge of the cup disappears. I really like the bubbles!</td>', 'I like how the left edge of the cup disappears. I really like the bubbles!', '2004-07-21 20:46:41.000000', NULL, 1),
(820980, 92518, 22010, '<td valign="top">Very creative! Poor m. :- (</td>', 'Very creative! Poor m. :- (', '2004-07-21 20:47:36.000000', NULL, 1),
(820982, 92276, 7628, '<td valign="top">good lighting - the highlights on both sides of the liquid really make it pop out from the background. 7</td>', 'good lighting - the highlights on both sides of the liquid really make it pop out from the background. 7', '2004-07-21 20:47:47.000000', NULL, 1),
(820985, 92519, 7628, '<td valign="top">I like the DOF here - just pickingout a narrow band in the middle.  Makes it feel like a landscape of chocolate. Nice detail, good light, color. 7</td>', 'I like the DOF here - just pickingout a narrow band in the middle.  Makes it feel like a landscape of chocolate. Nice detail, good light, color. 7', '2004-07-21 20:49:55.000000', NULL, 1),
(820986, 92675, 7628, '<td valign="top">nice texture - I like the chips.  Perhaps fewer chunks would give more subject focus - and the literal focus seems a bit soft.  Nice even lighting, but a bit steril - more scientific lighting than emotional.</td>', 'nice texture - I like the chips.  Perhaps fewer chunks would give more subject focus - and the literal focus seems a bit soft.  Nice even lighting, but a bit steril - more scientific lighting than emotional.', '2004-07-21 20:52:24.000000', NULL, 1),
(820988, 92671, 7628, '<td valign="top">What a sweet snake!  A novel idea to be sure.  The lighting is good on the snakes face, but the shadows are a bit red.  Wish the table had been white or black - a bit more neutral.  I don''t think you need the Toblerone package - the distinctive triangles are well known and the package just distracts the eye from the snake.</td>', 'What a sweet snake!  A novel idea to be sure.  The lighting is good on the snakes face, but the shadows are a bit red.  Wish the table had been white or black - a bit more neutral.  I don''t think you need the Toblerone package - the distinctive triangles are well known and the package just distracts the eye from the snake.', '2004-07-21 20:54:58.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(820990, 92502, 7628, '<td valign="top">I like the dramatic lighting and the narrow DOF, the effect is almost romantic.  I''d crop in a bit tighter to the chocolate.  There are some odd colors and graininess to the shadow at the back left - perhaps a bit to dramatic in the color adjustments?  Not a big deal. 6</td>', 'I like the dramatic lighting and the narrow DOF, the effect is almost romantic.  I''d crop in a bit tighter to the chocolate.  There are some odd colors and graininess to the shadow at the back left - perhaps a bit to dramatic in the color adjustments?  Not a big deal. 6', '2004-07-21 20:57:24.000000', NULL, 1),
(820992, 92282, 7628, '<td valign="top">These are very pretty berries and delicious looking globs of chocolate.  I''d like to see them in a plane bowl with a plain background.  They deserve to get all the attention.  Nice lightng anf an appropriate soft focus that makes it feel nostalgic.</td>', 'These are very pretty berries and delicious looking globs of chocolate.  I''d like to see them in a plane bowl with a plain background.  They deserve to get all the attention.  Nice lightng anf an appropriate soft focus that makes it feel nostalgic.', '2004-07-21 21:02:39.000000', NULL, 1),
(820993, 92051, 16408, '<td valign="top">blue chocolate?</td>', 'blue chocolate?', '2004-07-21 21:03:11.000000', NULL, 1),
(820994, 92552, 7628, '<td valign="top">I like how you''ve mmade the icecream and chocolate seem to float in a hazy dream of white.  The Narrow DOF works well here.  7</td>', 'I like how you''ve mmade the icecream and chocolate seem to float in a hazy dream of white.  The Narrow DOF works well here.  7', '2004-07-21 21:04:27.000000', NULL, 1),
(820996, 91356, 7628, '<td valign="top">Wow, that is WIDE dof.  Nice and bright, balanced composition, nice feeling.  I wonder that with everything in focus that it feel too busy.  My eye cannot settle on anything.</td>', 'Wow, that is WIDE dof.  Nice and bright, balanced composition, nice feeling.  I wonder that with everything in focus that it feel too busy.  My eye cannot settle on anything.', '2004-07-21 21:07:12.000000', NULL, 1),
(820997, 92542, 7628, '<td valign="top">I like the chocolate mood you''ve created by using all these brown/chocolate colors.  I wish you had gotten a large DOF so it could all be sharp - I think that would better suit the elegant lines and depth of contrast already in the shot.  yum!</td>', 'I like the chocolate mood you''ve created by using all these brown/chocolate colors.  I wish you had gotten a large DOF so it could all be sharp - I think that would better suit the elegant lines and depth of contrast already in the shot.  yum!', '2004-07-21 21:08:53.000000', NULL, 1),
(821001, 92642, 16408, '<td valign="top">the grain doesn''t look at all natural</td>', 'the grain doesn''t look at all natural', '2004-07-21 21:11:38.000000', NULL, 1),
(821002, 92129, 7628, '<td valign="top">Fabulous!  Great color, combination on subjects, wonderful lighting.  My only wish would be to have her against a flat dark ground - the texture of the grass competes with her hair. 9</td>', 'Fabulous!  Great color, combination on subjects, wonderful lighting.  My only wish would be to have her against a flat dark ground - the texture of the grass competes with her hair. 9', '2004-07-21 21:12:08.000000', NULL, 1),
(821003, 92642, 7628, '<td valign="top">I like the motion in this!  Creative.  I also like how the silver reflects the chocolate color so you get all those little lines with chocolate tones.  If you had held it still for part of the exposure would you get more definition and a more solid sense of the beater and the chocoate as well as the motion? Or a flash to stop the motion and get a solid image on top of the blur? 6</td>', 'I like the motion in this!  Creative.  I also like how the silver reflects the chocolate color so you get all those little lines with chocolate tones.  If you had held it still for part of the exposure would you get more definition and a more solid sense of the beater and the chocoate as well as the motion? Or a flash to stop the motion and get a solid image on top of the blur? 6', '2004-07-21 21:13:18.000000', NULL, 1),
(821013, 92690, 16408, '<td valign="top">creative thought but way too over exposed</td>', 'creative thought but way too over exposed', '2004-07-21 21:23:55.000000', NULL, 1),
(821014, 92163, 16408, '<td valign="top">doesn''t meet the challenge, did you read the details?</td>', 'doesn''t meet the challenge, did you read the details?', '2004-07-21 21:24:56.000000', NULL, 1),
(821015, 92005, 12825, '<td valign="top">Creative =)</td>', 'Creative =)', '2004-07-21 21:25:34.000000', NULL, 1),
