(821022, 92684, 22734, '<td valign="top">This is simply a riot. I am still laughing. Great !</td>', 'This is simply a riot. I am still laughing. Great !', '2004-07-21 21:33:08.000000', NULL, 1),
(821024, 92699, 19831, '<td valign="top">Great shot. Nice composition. Very creative. I like it. The drops on the table are a nice touch.</td>', 'Great shot. Nice composition. Very creative. I like it. The drops on the table are a nice touch.', '2004-07-21 21:38:10.000000', NULL, 1),
(821028, 92626, 19831, '<td valign="top">Seems awful small. You should use the full 640 allowed. It would show more detail. Looks like you should work on your lighting more. Seems like harsh light and shadows.</td>', 'Seems awful small. You should use the full 640 allowed. It would show more detail. Looks like you should work on your lighting more. Seems like harsh light and shadows.', '2004-07-21 21:40:11.000000', NULL, 1),
