(821036, 92667, 22310, '<td valign="top">Looks a little out of focus.  Maybe a little grainy.</td>', 'Looks a little out of focus.  Maybe a little grainy.', '2004-07-21 21:59:15.000000', NULL, 1),
(821044, 92574, 14863, '<td valign="top">Ah hahahaha! I love this- smily faces get me everytime. THis is adroiable and hi-larious- great job!</td>', 'Ah hahahaha! I love this- smily faces get me everytime. THis is adroiable and hi-larious- great job!', '2004-07-21 22:11:25.000000', NULL, 1),
