(821095, 91950, 6597, '<td valign="top">good colors 6</td>', 'good colors 6', '2004-07-21 22:51:06.000000', NULL, 1),
(821097, 92561, 6597, '<td valign="top">face good work 7</td>', 'face good work 7', '2004-07-21 22:52:42.000000', NULL, 1),
