(821623, 91787, 14671, '<td valign="top">wow nice macro shot.  Fantastic color and clarity.  good use of DOF and excellent positioning.  Looks like a picture in a calander rather then a wall hanging tho.  well done.  &lt;9&gt;</td>', 'wow nice macro shot.  Fantastic color and clarity.  good use of DOF and excellent positioning.  Looks like a picture in a calander rather then a wall hanging tho.  well done.  <9>', '2004-07-22 09:10:44.000000', NULL, 1),
(821624, 92056, 14671, '<td valign="top">looks blurry.  not a very interesting shot.  maybe if it was clearer and had a greater DOF it would have been a better shot.</td>', 'looks blurry.  not a very interesting shot.  maybe if it was clearer and had a greater DOF it would have been a better shot.', '2004-07-22 09:12:50.000000', NULL, 1),
