(821631, 92578, 14671, '<td valign="top">finally a picture that ould suggest "ART" instead of "advertising".  great composition, clarity, color, and use of chocolate.  Very nice and well done. &lt;10&gt;</td>', 'finally a picture that ould suggest "ART" instead of "advertising".  great composition, clarity, color, and use of chocolate.  Very nice and well done. <10>', '2004-07-22 09:17:58.000000', NULL, 1),
(821634, 92407, 14671, '<td valign="top">To me this doesn''t suggest chocolate but says advertising revisited.  Nice color, clarity and great use of DOF.</td>', 'To me this doesn''t suggest chocolate but says advertising revisited.  Nice color, clarity and great use of DOF.', '2004-07-22 09:19:39.000000', NULL, 1),
(821635, 91949, 14671, '<td valign="top">whats a one touch ultra???  nice use of a brown border and great clarity but I would have removed that machine and the M7M''s and just shot the bar.  In my opinion it would have scored much much higher especially since I realydon''t know what that machine is. &lt;5&gt;</td>', 'whats a one touch ultra???  nice use of a brown border and great clarity but I would have removed that machine and the M7M''s and just shot the bar.  In my opinion it would have scored much much higher especially since I realydon''t know what that machine is. <5>', '2004-07-22 09:21:31.000000', NULL, 1),
(821639, 92134, 14671, '<td valign="top">to me this really doesn''t express chocolate, it expresses advertisment revisited.a colorful picture and I don''t like the choice in your DOF.  The chocolate also looks kinda bland (meaning: light chocolate inside as well as outside).</td>', 'to me this really doesn''t express chocolate, it expresses advertisment revisited.a colorful picture and I don''t like the choice in your DOF.  The chocolate also looks kinda bland (meaning: light chocolate inside as well as outside).', '2004-07-22 09:26:04.000000', NULL, 1),
(821644, 91630, 14671, '<td valign="top">As it looks more like art then advertising like some of the other pictures I''ve viewed to me it does not portray chocolate.  it actually looks more like insense.  However nice clarity and DOF.</td>', 'As it looks more like art then advertising like some of the other pictures I''ve viewed to me it does not portray chocolate.  it actually looks more like insense.  However nice clarity and DOF.', '2004-07-22 09:29:35.000000', NULL, 1),
(821645, 92497, 14671, '<td valign="top">I would have cropped out the right side of the picture not exposing the chair at all or very little of it.  Centering the composition takes a lot more away then it gives I find.  Using the rule of thirds would have made this a better shot in my opinion.  Nice colors and clarity. &lt;7&gt;</td>', 'I would have cropped out the right side of the picture not exposing the chair at all or very little of it.  Centering the composition takes a lot more away then it gives I find.  Using the rule of thirds would have made this a better shot in my opinion.  Nice colors and clarity. <7>', '2004-07-22 09:33:20.000000', NULL, 1),
(821649, 92643, 14671, '<td valign="top">Great shot.  excellent color, clarity, composition and positioning.  Looks more like "photographic art" instead of advertising and a shot I would expect to see on display.  well done.  &lt;9&gt;</td>', 'Great shot.  excellent color, clarity, composition and positioning.  Looks more like "photographic art" instead of advertising and a shot I would expect to see on display.  well done.  <9>', '2004-07-22 09:39:14.000000', NULL, 1),
(821651, 92535, 14671, '<td valign="top">nice shot but to me it does not capture the spirit of this challenge.  Looks more like it was shot because it was close to you house or you just happened to be passing by and saw it.  I like the angle you captured it on and nice clarity but its just not my cup of tea so to speak. &lt;6&gt;</td>', 'nice shot but to me it does not capture the spirit of this challenge.  Looks more like it was shot because it was close to you house or you just happened to be passing by and saw it.  I like the angle you captured it on and nice clarity but its just not my cup of tea so to speak. <6>', '2004-07-22 09:42:24.000000', NULL, 1),
(821653, 92578, 17551, '<td valign="top">Oh to be the chocolate zorro. Great shot, I really like the subtle lighting. 9.</td>', 'Oh to be the chocolate zorro. Great shot, I really like the subtle lighting. 9.', '2004-07-22 09:45:28.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(821656, 92659, 14671, '<td valign="top">In my opinion this is not a very appealing shot.  The chocolate does not look dark enough to pull this shot off.  Glad to see hat it looks more like art the advertising tho.  nice lighting and clarity and composition, just not fussy on the color of the chocolate.  it looks to me more like body paint or something along thoise lines. &lt;7&gt;</td>', 'In my opinion this is not a very appealing shot.  The chocolate does not look dark enough to pull this shot off.  Glad to see hat it looks more like art the advertising tho.  nice lighting and clarity and composition, just not fussy on the color of the chocolate.  it looks to me more like body paint or something along thoise lines. <7>', '2004-07-22 09:49:54.000000', NULL, 1),
(821659, 92148, 14671, '<td valign="top">lol a funny.  great shot. I like the way it looks like art instead of advertising revisited challenge.  &lt;7&gt;</td>', 'lol a funny.  great shot. I like the way it looks like art instead of advertising revisited challenge.  <7>', '2004-07-22 09:52:46.000000', NULL, 1),
(821670, 92671, 19841, '<td valign="top">If the forbidden fruit had been chocolate, Eve would never have offered any to Adam...<br/> <br/>Great idea, and a pretty snake!</td>', 'If the forbidden fruit had been chocolate, Eve would never have offered any to Adam... Great idea, and a pretty snake!', '2004-07-22 10:09:28.000000', NULL, 1),
(821675, 91563, 19841, '<td valign="top">A bold graphic image like this needs even lighting.  The darkness at the bottom spoils the "happy" idea.</td>', 'A bold graphic image like this needs even lighting.  The darkness at the bottom spoils the "happy" idea.', '2004-07-22 10:15:03.000000', NULL, 1),
(821677, 92029, 14671, '<td valign="top">a photo that you would expect to see in a chcoclate shop is always nice to see.  beats the others pics in this challenge that look more like advertising revisited.  nice composition and clarity. &lt;7&gt;</td>', 'a photo that you would expect to see in a chcoclate shop is always nice to see.  beats the others pics in this challenge that look more like advertising revisited.  nice composition and clarity. <7>', '2004-07-22 10:17:12.000000', NULL, 1),
(821681, 92371, 14671, '<td valign="top">I find with the white background it is to bright and takes a lot away from the picture.</td>', 'I find with the white background it is to bright and takes a lot away from the picture.', '2004-07-22 10:20:51.000000', NULL, 1),
(821687, 92398, 14671, '<td valign="top">This is a very dark photo.  I like the lighting and its nice to see a photo that looks like art then advertising revisited.  This photo is something I would expect to see in a high class bar or liquor shop.  a very elegant photo.  well done. &lt;8&gt;</td>', 'This is a very dark photo.  I like the lighting and its nice to see a photo that looks like art then advertising revisited.  This photo is something I would expect to see in a high class bar or liquor shop.  a very elegant photo.  well done. <8>', '2004-07-22 10:27:04.000000', NULL, 1),
(821690, 91771, 14671, '<td valign="top">nice photo but I would have used a slightly darker chocolate.  I find this adds a great affect to the red strawberry. nice background, great color clarity and sharpness.  also a nice touch with the dripping chocolate. &lt;8&gt;</td>', 'nice photo but I would have used a slightly darker chocolate.  I find this adds a great affect to the red strawberry. nice background, great color clarity and sharpness.  also a nice touch with the dripping chocolate. <8>', '2004-07-22 10:31:48.000000', NULL, 1),
(821694, 92096, 14671, '<td valign="top">I don''t like the choice of DOF in this picture.  The foreground makes it hard to tell what the shot is about and has created a hotspot that takes away from the overall picture.</td>', 'I don''t like the choice of DOF in this picture.  The foreground makes it hard to tell what the shot is about and has created a hotspot that takes away from the overall picture.', '2004-07-22 10:34:21.000000', NULL, 1),
(821695, 92398, 19841, '<td valign="top">Great idea, but a little dark.</td>', 'Great idea, but a little dark.', '2004-07-22 10:34:49.000000', NULL, 1),
