(823382, 92382, 24169, '<td valign="top">Too much reflection off the egg.</td>', 'Too much reflection off the egg.', '2004-07-23 16:11:17.000000', NULL, 1),
(823383, 92642, 24169, '<td valign="top">I like it. Perhaps if the ISO had been slightly lower as it seems a little grainy?</td>', 'I like it. Perhaps if the ISO had been slightly lower as it seems a little grainy?', '2004-07-23 16:11:18.000000', NULL, 1),
(823384, 92534, 22748, '<td valign="top">This photo saddens me because I like it a lot, but there are a few serious problems with it. First, it''s extremely blurry. Out of focus, probably. I would have focused on the chocolate bar with the bit out of it in the foreground. Second, there is that ugly date stamp on it. What''s with that? I''ve never seem that in a challenge entry before. <br/> <br/>What kind of camera stamps the images with a date?! Maybe a video camera?<br/> <br/>Great idea &amp; composition.  Unfortunately, technical problems kill it.</td>', 'This photo saddens me because I like it a lot, but there are a few serious problems with it. First, it''s extremely blurry. Out of focus, probably. I would have focused on the chocolate bar with the bit out of it in the foreground. Second, there is that ugly date stamp on it. What''s with that? I''ve never seem that in a challenge entry before.  What kind of camera stamps the images with a date?! Maybe a video camera? Great idea & composition.  Unfortunately, technical problems kill it.', '2004-07-23 16:12:14.000000', NULL, 1),
(823385, 92524, 24169, '<td valign="top">Quite well executed and nice colours.</td>', 'Quite well executed and nice colours.', '2004-07-23 16:12:29.000000', NULL, 1),
(823390, 92684, 22748, '<td valign="top">Wow! Brilliant. The blue sky in the background is a nice touch too. Some clouds could make it even better maybe.  Good focus, exposure, framing. What is the boat made of?</td>', 'Wow! Brilliant. The blue sky in the background is a nice touch too. Some clouds could make it even better maybe.  Good focus, exposure, framing. What is the boat made of?', '2004-07-23 16:24:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(823396, 92326, 20066, '<td valign="top">I think your picture could have been better in color.</td>', 'I think your picture could have been better in color.', '2004-07-23 16:33:36.000000', NULL, 1),
(823397, 92276, 21183, '<td valign="top">The dark background is lovely and I like the way the lighting picks out the stream of melted chocolate, then gently strokes the curves of the bar underneath, ending in shadow at the front, which blends into the background.  I like the angle, making the light pick out the whole one side of the bar - making for both an interesting and artistic contrast and perspective to the whole image.  I''m no photography expert, neither am I qualified to be able to make ''technical'' criticisms, but I think the photo works really well.  I''m undecided about the frame. Anyway - gets my 10.</td>', 'The dark background is lovely and I like the way the lighting picks out the stream of melted chocolate, then gently strokes the curves of the bar underneath, ending in shadow at the front, which blends into the background.  I like the angle, making the light pick out the whole one side of the bar - making for both an interesting and artistic contrast and perspective to the whole image.  I''m no photography expert, neither am I qualified to be able to make ''technical'' criticisms, but I think the photo works really well.  I''m undecided about the frame. Anyway - gets my 10.', '2004-07-23 16:34:50.000000', NULL, 1),
(823406, 92415, 12573, '<td valign="top">Perhaps a little too close for comfort.  Would have liked more contrast and a more perfect piece of chocolate.</td>', 'Perhaps a little too close for comfort.  Would have liked more contrast and a more perfect piece of chocolate.', '2004-07-23 16:42:16.000000', NULL, 1),
(823408, 92377, 12573, '<td valign="top">If only you''d left out the shaker and the chocolate on the bottom.  I love the simplicity of the martini glass and the complementary swirls in the glass and chocolate.</td>', 'If only you''d left out the shaker and the chocolate on the bottom.  I love the simplicity of the martini glass and the complementary swirls in the glass and chocolate.', '2004-07-23 16:45:40.000000', NULL, 1),
(823409, 92396, 21183, '<td valign="top">I like the creative idea of a real orange dipped in chocolate. This photo definitely portrays an ''orange peel'' effect.  However, I feel it would help, with this particular photo, to see more colour contrast - or  even greater contrasts in the lights and darks.</td>', 'I like the creative idea of a real orange dipped in chocolate. This photo definitely portrays an ''orange peel'' effect.  However, I feel it would help, with this particular photo, to see more colour contrast - or  even greater contrasts in the lights and darks.', '2004-07-23 16:46:50.000000', NULL, 1),
(823410, 92400, 12573, '<td valign="top">Very nice high key photograph. I''m conflicted about the use of the leaves.  They seem somewhat out of place but their tone fits the composition of colors nicely.  I think the stem in the upper right of the "jar" could have been omitted to greater effect.</td>', 'Very nice high key photograph. I''m conflicted about the use of the leaves.  They seem somewhat out of place but their tone fits the composition of colors nicely.  I think the stem in the upper right of the "jar" could have been omitted to greater effect.', '2004-07-23 16:47:48.000000', NULL, 1),
(823412, 91881, 12573, '<td valign="top">Clever and well placed subject.  Too bad it is out of focus.  If that''s the effect you were going for, I would have to question the choice of soft focus in this kind of shot.</td>', 'Clever and well placed subject.  Too bad it is out of focus.  If that''s the effect you were going for, I would have to question the choice of soft focus in this kind of shot.', '2004-07-23 16:48:50.000000', NULL, 1),
(823416, 92613, 6172, '<td valign="top">child abuse</td>', 'child abuse', '2004-07-23 16:51:49.000000', NULL, 1),
(823419, 92218, 6172, '<td valign="top">gotta add a point just for the humor factor! :)</td>', 'gotta add a point just for the humor factor! :)', '2004-07-23 16:54:00.000000', NULL, 1),
(823420, 92580, 12573, '<td valign="top">I think this could benefit from a shallower DOF.  Also, the inclusion of the chips along with the powder and bar is a little too much for one photo, IMHO.  I love the light falling on the bar, though.  Nice effort.</td>', 'I think this could benefit from a shallower DOF.  Also, the inclusion of the chips along with the powder and bar is a little too much for one photo, IMHO.  I love the light falling on the bar, though.  Nice effort.', '2004-07-23 16:54:31.000000', NULL, 1),
(823424, 91771, 6172, '<td valign="top">the only chocolate strawberry photo in this competition I like.  just a little too much glare on the lower part of the strawberry</td>', 'the only chocolate strawberry photo in this competition I like.  just a little too much glare on the lower part of the strawberry', '2004-07-23 16:55:51.000000', NULL, 1),
(823427, 92416, 12573, '<td valign="top">Hmm. Very nice treatment of a truffle.  The background chocolates are a little too dark to see very well and could have probably been left out or given a little more light.  OVerall, the shot is very dark and moody...which is rather nice.</td>', 'Hmm. Very nice treatment of a truffle.  The background chocolates are a little too dark to see very well and could have probably been left out or given a little more light.  OVerall, the shot is very dark and moody...which is rather nice.', '2004-07-23 16:57:26.000000', NULL, 1),
(823430, 91640, 24550, '<td valign="top">excellent flame</td>', 'excellent flame', '2004-07-23 16:59:36.000000', NULL, 1),
(823432, 92397, 12573, '<td valign="top">Lighting is a little too, umm, even or something.  The glare coming off the surface of the chocolate takes away from an otherwise interesting composition.  I wish I could tell what was being dipped.  And my goodness, that fork looks huge.  It kinda overpowers the chocolate.</td>', 'Lighting is a little too, umm, even or something.  The glare coming off the surface of the chocolate takes away from an otherwise interesting composition.  I wish I could tell what was being dipped.  And my goodness, that fork looks huge.  It kinda overpowers the chocolate.', '2004-07-23 16:59:47.000000', NULL, 1),
(823434, 92518, 12573, '<td valign="top">Hilarious.  The choice of yellow lined paper is an odd one.  Still, the power and simplicity of the composition almost makes up for any technical errors.  8!</td>', 'Hilarious.  The choice of yellow lined paper is an odd one.  Still, the power and simplicity of the composition almost makes up for any technical errors.  8!', '2004-07-23 17:01:58.000000', NULL, 1),
(823436, 92504, 12573, '<td valign="top">Slightly strange placement of chocolate into the scene.  One of the kisses looks to be melting off the glass.  Also, the reflections in the wine glass are so prominent, they pull my eye away from the shadow kissers.</td>', 'Slightly strange placement of chocolate into the scene.  One of the kisses looks to be melting off the glass.  Also, the reflections in the wine glass are so prominent, they pull my eye away from the shadow kissers.', '2004-07-23 17:05:09.000000', NULL, 1),
(823437, 92243, 20539, '<td valign="top">great setup. good idea.</td>', 'great setup. good idea.', '2004-07-23 17:06:05.000000', NULL, 1),
(823438, 92268, 12573, '<td valign="top">Excellent work.  I only wish the white "chip" was more white than cream in color.  I love that you faced them all in the same direction and put the heat to them.</td>', 'Excellent work.  I only wish the white "chip" was more white than cream in color.  I love that you faced them all in the same direction and put the heat to them.', '2004-07-23 17:06:18.000000', NULL, 1),
(823441, 92626, 21183, '<td valign="top">This photo, to me, portrays a very ''christmassy'' feel to it - with the hollies and berries on the plate.  It looks nice against the colourful chocolate beans.  I would love to see the entire plate filled with only the beans, leaving the red dots and pattern on the plate surrounding them, all against a plain, contrasting coloured, unruffled background.  But I''m no expert - just a thought.</td>', 'This photo, to me, portrays a very ''christmassy'' feel to it - with the hollies and berries on the plate.  It looks nice against the colourful chocolate beans.  I would love to see the entire plate filled with only the beans, leaving the red dots and pattern on the plate surrounding them, all against a plain, contrasting coloured, unruffled background.  But I''m no expert - just a thought.', '2004-07-23 17:08:51.000000', NULL, 1),
(823443, 92684, 20539, '<td valign="top">this is a great idea, with an awsome title, but i think the shot could have been worked on a little more. with a sharper image and a better backround, this idea could have made it to the top 10.</td>', 'this is a great idea, with an awsome title, but i think the shot could have been worked on a little more. with a sharper image and a better backround, this idea could have made it to the top 10.', '2004-07-23 17:12:19.000000', NULL, 1),
(823444, 92365, 20539, '<td valign="top">mmm, just wanna take a big bite out of it!!! i love overdosing on chocolate.</td>', 'mmm, just wanna take a big bite out of it!!! i love overdosing on chocolate.', '2004-07-23 17:13:16.000000', NULL, 1),
(823451, 92581, 24565, '<td valign="top">Very cute</td>', 'Very cute', '2004-07-23 17:19:44.000000', NULL, 1),
(823453, 92675, 24565, '<td valign="top">good title</td>', 'good title', '2004-07-23 17:20:10.000000', NULL, 1),
(823455, 91994, 24565, '<td valign="top">I like it very inagenative</td>', 'I like it very inagenative', '2004-07-23 17:21:12.000000', NULL, 1),
(823457, 92268, 24565, '<td valign="top">good one!!!</td>', 'good one!!!', '2004-07-23 17:22:52.000000', NULL, 1),
(823463, 92129, 21183, '<td valign="top">It never occured to me that it would be possible to take a portrait shot such as this, with a model, and still be able to maintain ''chocolate'' as being the subject of focus.  I think you''ve achieved this very well, though the models eyes almost win over.  I like the colour and the lighting.  The model''s hair colour seems perfect for this photo.  I''m neither a photography nor a ''technical'' expert, who can make qualified criticisms, but I think the whole photo is really beautiful and I gave it a 9.</td>', 'It never occured to me that it would be possible to take a portrait shot such as this, with a model, and still be able to maintain ''chocolate'' as being the subject of focus.  I think you''ve achieved this very well, though the models eyes almost win over.  I like the colour and the lighting.  The model''s hair colour seems perfect for this photo.  I''m neither a photography nor a ''technical'' expert, who can make qualified criticisms, but I think the whole photo is really beautiful and I gave it a 9.', '2004-07-23 17:28:37.000000', NULL, 1),
(823470, 92578, 21183, '<td valign="top">I really like the contrasts of shape, shade and lighting and skin tones on this.  It looks a ''warm'' image. I like the way the chocolate has been used so creatively in the photo.  I''m not a photo expert and neither am I qualified to make any technical criticisms, but for me this photograph works really well and I gave it a 9</td>', 'I really like the contrasts of shape, shade and lighting and skin tones on this.  It looks a ''warm'' image. I like the way the chocolate has been used so creatively in the photo.  I''m not a photo expert and neither am I qualified to make any technical criticisms, but for me this photograph works really well and I gave it a 9', '2004-07-23 17:38:08.000000', NULL, 1),
(823471, 92658, 7696, '<td valign="top">I like the idea. I think just the bottle and the glass would of been enough.</td>', 'I like the idea. I think just the bottle and the glass would of been enough.', '2004-07-23 17:38:48.000000', NULL, 1),
(823477, 92607, 4562, '<td valign="top">nice picture, the lighting is off.  this would be a great pic if the background was white and the cup was brighter(light).....</td>', 'nice picture, the lighting is off.  this would be a great pic if the background was white and the cup was brighter(light).....', '2004-07-23 18:00:48.000000', NULL, 1),
