(823488, 92644, 14614, '<td valign="top">I''d like a bit more light on the whole image or a "spot light" to highlight one element (between the blue boa, b''case with letters, chocolate, hands there''s a bit too much fighting for attention)</td>', 'I''d like a bit more light on the whole image or a "spot light" to highlight one element (between the blue boa, b''case with letters, chocolate, hands there''s a bit too much fighting for attention)', '2004-07-23 18:11:16.000000', NULL, 1),
