(823490, 92005, 4562, '<td valign="top">nice..in a sorta wierd way.......one thing tho.....bring your subjects in closer together...</td>', 'nice..in a sorta wierd way.......one thing tho.....bring your subjects in closer together...', '2004-07-23 18:12:10.000000', NULL, 1),
