(824148, 92497, 21767, '<td valign="top">thats cute</td>', 'thats cute', '2004-07-24 15:37:17.000000', NULL, 1),
(824150, 92400, 15475, '<td valign="top">I love the color on the leaves.  Good setting, good lighting.  I think this is a good concept picture.</td>', 'I love the color on the leaves.  Good setting, good lighting.  I think this is a good concept picture.', '2004-07-24 15:38:36.000000', NULL, 1),
(824151, 92556, 15475, '<td valign="top">this might have looked better in color, no?</td>', 'this might have looked better in color, no?', '2004-07-24 15:39:08.000000', NULL, 1),
(824152, 92690, 11895, '<td valign="top">the banana looks over exposed to me, and the background is washed out, the drop at the left is just floating, there needs to some texture or color to the background</td>', 'the banana looks over exposed to me, and the background is washed out, the drop at the left is just floating, there needs to some texture or color to the background', '2004-07-24 15:40:46.000000', NULL, 1),
(824154, 92015, 15475, '<td valign="top">I know exactly how you feel... I love the expression on the face and perfect setting for the chocolate.  I hope this picture does well.</td>', 'I know exactly how you feel... I love the expression on the face and perfect setting for the chocolate.  I hope this picture does well.', '2004-07-24 15:41:53.000000', NULL, 1),
(824155, 92524, 15475, '<td valign="top">Very nice!  Very abstract!</td>', 'Very nice!  Very abstract!', '2004-07-24 15:42:35.000000', NULL, 1),
(824158, 92642, 15475, '<td valign="top">Makes me feel a bit dizzy.. but a sweety dizziness.</td>', 'Makes me feel a bit dizzy.. but a sweety dizziness.', '2004-07-24 15:43:23.000000', NULL, 1),
(824159, 91881, 15475, '<td valign="top">One of a kind.</td>', 'One of a kind.', '2004-07-24 15:43:39.000000', NULL, 1),
(824160, 92684, 15475, '<td valign="top">If my boat were on a chocolate ocean, I''d go fishing everyday!</td>', 'If my boat were on a chocolate ocean, I''d go fishing everyday!', '2004-07-24 15:44:21.000000', NULL, 1),
(824161, 91640, 15475, '<td valign="top">A creative concept.</td>', 'A creative concept.', '2004-07-24 15:44:57.000000', NULL, 1),
(824162, 92089, 15475, '<td valign="top">What''s a break without KitKat!?</td>', 'What''s a break without KitKat!?', '2004-07-24 15:45:56.000000', NULL, 1),
(824163, 91640, 23471, '<td valign="top">Really liked this...though i think that the stick coming from the bottom of the mug is unnecessary.</td>', 'Really liked this...though i think that the stick coming from the bottom of the mug is unnecessary.', '2004-07-24 15:46:03.000000', NULL, 1),
