(824171, 91679, 15475, '<td valign="top">A black background with a steam coming out of the cup would have been a really "hot" cocoA!</td>', 'A black background with a steam coming out of the cup would have been a really "hot" cocoA!', '2004-07-24 15:53:27.000000', NULL, 1),
