(824197, 92613, 164, '<td valign="top">I hope this was not deliberate.</td>', 'I hope this was not deliberate.', '2004-07-24 16:22:56.000000', NULL, 1),
(824198, 91688, 164, '<td valign="top">Too much glare. It distracts from the picture</td>', 'Too much glare. It distracts from the picture', '2004-07-24 16:24:03.000000', NULL, 1),
(824243, 92553, 21183, '<td valign="top">The lighting from beneath / inside the tower of kitkat fingers really does make it look like a hot furnace, and I like the way that the white light picks out the corners and angles at the top of the tower. Not sure about the bar propped up at the lower side, wondering if the photo might be without it altogether?</td>', 'The lighting from beneath / inside the tower of kitkat fingers really does make it look like a hot furnace, and I like the way that the white light picks out the corners and angles at the top of the tower. Not sure about the bar propped up at the lower side, wondering if the photo might be without it altogether?', '2004-07-24 17:45:37.000000', NULL, 1),
(824255, 91771, 24604, '<td valign="top">Very nice image.</td>', 'Very nice image.', '2004-07-24 18:03:11.000000', NULL, 1),
(824257, 92504, 24604, '<td valign="top">A+ for originality.</td>', 'A+ for originality.', '2004-07-24 18:06:21.000000', NULL, 1),
(824265, 92581, 19446, '<td valign="top">great idea &amp; composition.</td>', 'great idea & composition.', '2004-07-24 18:39:25.000000', NULL, 1),
(824275, 92399, 24072, '<td valign="top">Looks like it was a pretty nice shot but it''s sooo small it''s really hard to tell.</td>', 'Looks like it was a pretty nice shot but it''s sooo small it''s really hard to tell.', '2004-07-24 19:18:57.000000', NULL, 1),
(824277, 91771, 24072, '<td valign="top">very nice! I give it a 10</td>', 'very nice! I give it a 10', '2004-07-24 19:21:12.000000', NULL, 1),
