(824280, 92218, 24595, '<td valign="top">Not a big fan of the little wooden guys.  Found it a bit hard to gain a sense of depth with the choice of background, and the close proximity.</td>', 'Not a big fan of the little wooden guys.  Found it a bit hard to gain a sense of depth with the choice of background, and the close proximity.', '2004-07-24 19:25:33.000000', NULL, 1),
