(825856, 92661, 23251, '<td valign="top">The DOF is a little to tight in this and the colour (Silver) stops any chance of defination of the background kisses.  I think a different choice of base colour would have helped also.</td>', 'The DOF is a little to tight in this and the colour (Silver) stops any chance of defination of the background kisses.  I think a different choice of base colour would have helped also.', '2004-07-26 10:20:04.000000', NULL, 1),
(825861, 92656, 2716, '<td valign="top">That ... is toooooooooooooooooooooo funyyyyyyy!!!!  Jacko.  well deserved 10.</td>', 'That ... is toooooooooooooooooooooo funyyyyyyy!!!!  Jacko.  well deserved 10.', '2004-07-26 10:25:50.000000', NULL, 1),
(825893, 92523, 23251, '<td valign="top">Not sure what it is but it lacks punch for me.  Its a bit grainy as well.  The dark bottom edge and right edge also draws my attention. Not sure what I''d do to make it better.</td>', 'Not sure what it is but it lacks punch for me.  Its a bit grainy as well.  The dark bottom edge and right edge also draws my attention. Not sure what I''d do to make it better.', '2004-07-26 10:52:22.000000', NULL, 1),
(825895, 92399, 23251, '<td valign="top">Very small image, could it be made at 640 dpi?  I''m sure it would help your score!</td>', 'Very small image, could it be made at 640 dpi?  I''m sure it would help your score!', '2004-07-26 10:53:31.000000', NULL, 1),
(825897, 92355, 23251, '<td valign="top">There seems to be a lot of waisted area at the bottom of the photo.  Maybe a tighter crop at that end and more of the chocolate roses.</td>', 'There seems to be a lot of waisted area at the bottom of the photo.  Maybe a tighter crop at that end and more of the chocolate roses.', '2004-07-26 10:55:23.000000', NULL, 1),
