(830621, 92450, 7810, '<td valign="top">Unbelievable...nice shot<br/></td>', 'Unbelievable...nice shot', '2004-07-28 19:33:51.000000', NULL, 0),
(830655, 92646, 1031, '<td valign="top">Thanks for one of the best batch of comments I''ve gotten in a long time. This was kind of a last-minute alternate idea when I realized I wasn''t going to make it to any of the local chocolatiers ...<br/> <br/>The father of my "best friend" from fourth grade through high school was the regional distributor for Lindt and ALL KINDS of other imported candies, and we were pretty familiar with the cupboard where the out-of-date sample stock ended up ... the gift and fancy food trade shows we went to were pretty awesome as well. : )</td>', 'Thanks for one of the best batch of comments I''ve gotten in a long time. This was kind of a last-minute alternate idea when I realized I wasn''t going to make it to any of the local chocolatiers ... The father of my "best friend" from fourth grade through high school was the regional distributor for Lindt and ALL KINDS of other imported candies, and we were pretty familiar with the cupboard where the out-of-date sample stock ended up ... the gift and fancy food trade shows we went to were pretty awesome as well. : )', '2004-07-28 19:45:45.000000', NULL, 0),
(830688, 92201, 9136, '<td valign="top">Thanks for everyone that commented... this was my first submission, just happy I didn''t get last. I''ll take your suggestions and try again next time. :)</td>', 'Thanks for everyone that commented... this was my first submission, just happy I didn''t get last. I''ll take your suggestions and try again next time. :)', '2004-07-28 20:10:09.000000', NULL, 0),
